const cityRank = (c, city) => { const list = (c.cities || []).map((n) => cityAt(n, S.year)); const i = list.indexOf(city); return i < 0 ? 3 : i; };
const _wageOfCity = wageOf;
wageOf = function (x) { const c = C(); const r = S && S.city ? cityRank(c, S.city) : 2; return Math.round(_wageOfCity(x) * (r === 0 ? 1.12 : r >= 4 ? 0.92 : 1)); };
