const CHRON_SKIP = /^(📰|🗞️|🌸|☀️|🍂|❄️|🌧️|⛈️|☃️|🌦️|🎄|🎆|🎃|🏖️|🎶|🎵|🍼 Достижение|🎂 День рождения|💡 Распространяется|🧠 Ваше внимание)/u;
function chronicle() {
  const out = [];
  for (const b of S.log) {
    const items = b.items.filter((i) => i.t && !CHRON_SKIP.test(i.t) && !/Достижение «/.test(i.t));
    const pick2 = items.filter((i) => i.c === 'good' || i.c === 'bad').concat(items.filter((i) => i.c !== 'good' && i.c !== 'bad')).slice(0, 3);
    if (pick2.length) out.push({ y: b.year, a: b.age, items: pick2.map((i) => i.t) });
  }
  return out;
}
const CHAPTER_T = { '👶 Раннее детство': ['👶 Early childhood', '👶 Раннє дитинство'], '🎒 Школьные годы': ['🎒 School years', '🎒 Шкільні роки'], '🌱 Юность': ['🌱 Youth', '🌱 Юність'], '💼 Зрелость': ['💼 Adulthood', '💼 Зрілість'], '🏡 Опыт': ['🏡 Experience', '🏡 Досвід'], '🌅 Мудрость': ['🌅 Wisdom', '🌅 Мудрість'] };
const CHAPTERS = [[0, 6, '👶 Раннее детство'], [7, 17, '🎒 Школьные годы'], [18, 29, '🌱 Юность'], [30, 49, '💼 Зрелость'], [50, 64, '🏡 Опыт'], [65, 200, '🌅 Мудрость']];
